params.command:
$ErrorActionPreference='Stop'
$relay=Join-Path $HOME 'HeavenBridgeRepo'
$origin=(git -C $relay remote get-url origin).Trim()
$tmp=Join-Path $env:TEMP ('agentcontrol-capacity-'+[guid]::NewGuid().ToString('N'))
git clone --quiet --branch main --single-branch $origin $tmp
if($LASTEXITCODE -ne 0){ exit $LASTEXITCODE }
try {
  $sha=(git -C $tmp rev-parse HEAD).Trim()
  Set-Location (Join-Path $tmp 'tools\agent-control')
  npm run check
  if($LASTEXITCODE -ne 0){ exit $LASTEXITCODE }
  npm test
  if($LASTEXITCODE -ne 0){ exit $LASTEXITCODE }
  Write-Output ('AGENT_CONTROL_VERIFIED_SHA='+$sha)
} finally {
  Set-Location $HOME
  Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue
}
